export const meta = {
  "slug": "tabler-copy",
  "family": "tabler",
  "name": "copy",
  "category": "Files",
  "motion": "copy",
  "component": "createTablerCopyIcon"
};

export function createTablerCopyIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
